package net.spell_engine.particle;
import net.minecraft.entity.Entity; import net.minecraft.world.World; import net.spell_engine.api.spell.ParticleBatch; import java.util.*;
public final class ParticleHelper { private ParticleHelper(){} private static List<net.spell_engine.api.spell.fx.ParticleGroup> convert(ParticleBatch[] a){if(a==null)return List.of();return Arrays.stream(a).filter(Objects::nonNull).map(ParticleBatch::toModern).toList();} public static void sendBatches(Entity e,ParticleBatch[] a){net.spell_engine.fx.ParticleHelper.sendBatches(e,convert(a));} public static void sendBatches(Entity e,ParticleBatch[] a,boolean include){net.spell_engine.fx.ParticleHelper.sendBatches(e,convert(a),include);} public static void play(World w,Entity e,ParticleBatch[] a){net.spell_engine.fx.ParticleHelper.play(w,e,convert(a));} }
